-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"7af93dac-bf86-4c5a-9aa1-8d9152fb87a4","n":1,"title":"أدوات الشرط الجازمة","passage":"تربط أدوات الشرط الجازمة فعل الشرط بالجواب، وتجزم فعلين مضارعين إذا كانا مضارعين قابلين للجزم. في «إنْ تجتهدْ تنجحْ» جُزم الفعلان بالسكون الظاهر؛ وقد يختلف موضع علامة الجزم في الأفعال المعتلة أو الأفعال الخمسة. تُحدد الأداة والعلاقة قبل الإعراب.","question":"ما الأداة الجازمة في «إن تجتهد تنجح»؟","correct":"إنْ","wrong":["لو","إذا","لولا"],"practice":"أنشئ ثلاث جمل بأدوات شرط جازمة مختلفة، واضبط الفعل والجواب.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"7af93dac-bf86-4c5a-9aa1-8d9152fb87a4","n":2,"title":"أدوات الشرط غير الجازمة","passage":"تُستعمل «لو» و«لولا» و«إذا» في تراكيب شرطية تختلف دلالتها من الامتناع والتحضيض إلى الاستقبال والسياق، لكنها لا تجزم الفعلين كـ«إنْ». في «إذا حضرتَ بدأنا» يرتبط بدء العمل بحضور المخاطب دون أثر جزم أداة إن.","question":"أي أداة شرط غير جازمة في «إذا حضرت بدأنا»؟","correct":"إذا","wrong":["إنْ","مَن","مهما"],"practice":"قارن ثلاثة تراكيب شرطية جازمة وغير جازمة من حيث المعنى وأثر الإعراب.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"7af93dac-bf86-4c5a-9aa1-8d9152fb87a4","n":3,"title":"اقتران جواب الشرط بالفاء","passage":"قد يقترن جواب الشرط بالفاء وجوبًا في صور محددة عندما لا يصلح مباشرة لأن يكون جوابًا مجزومًا، مثل الجملة الاسمية في «إنْ تجتهدْ فأنتَ ناجحٌ». لا تُضاف الفاء لكل جواب بلا تحليل نوع الجملة.","question":"لماذا اقترن جواب الشرط بالفاء في «فأنت ناجح»؟","correct":"لأن الجواب جملة اسمية","wrong":["لأن الشرط بلا فعل","لأنها فاء عطف فقط","لأن كل جواب شرط يقتضي الفاء"],"practice":"اكتب أربعة أجوبة للشرط، وحدد الحالات التي تحتاج الفاء مع تعليل.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"7af93dac-bf86-4c5a-9aa1-8d9152fb87a4","n":4,"title":"جزم المضارع في جواب الطلب","passage":"يجوز جزم مضارع واقع جوابًا لطلب بشروط تتعلق بالمعنى والربط، مثل «اجتهدْ تنجحْ»؛ يمكن تأويل الجملة بشرط «إن تجتهد تنجح». لا يُجزم كل مضارع بعد أمر؛ يجب تحقق السببية وإمكان المعنى.","question":"متى يُجزم المضارع جوابًا للطلب في التحليل المدرسي؟","correct":"عند تحقق معنى السببية وإمكان تأويله بشرط","wrong":["بعد أي فعل أمر بلا شرط","لمجرد وقوعه آخر الجملة","إذا سبق حرف جر"],"practice":"كوّن ثلاثة أمثلة لجزم جواب الطلب، ومثالًا لا يصح فيه الجزم مع تفسير.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":1,"title":"تقسيم الاسم إلى جامد ومشتق","passage":"الجامد في التقسيم الصرفي لا يُنظر إليه بوصفه مأخوذًا من أصل فعل وفق المشتقات القياسية، مثل «شمس»، بينما «كاتب» مشتق من كتب. بعض الكلمات تحتاج مراجعة المعجم ولا تكفي حروفها للحكم على بنائها التاريخي.","question":"أي كلمة اسم مشتق في المقارنة؟","correct":"كاتب","wrong":["شمس","بحر","جبل"],"practice":"صنف ثمانية أسماء إلى جامدة ومشتقة واذكر قرينة كل اختيار.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":2,"title":"أنواع الأسماء المشتقة","passage":"تشمل الأنواع المدروسة من الأسماء المشتقة اسم الفاعل واسم المفعول وصيغ المبالغة والصفة المشبهة واسم التفضيل وأسماء الزمان والمكان والآلة بحسب الباب. يربط المتعلم الصيغة بوظيفتها ودلالة السياق ولا يكتفي بقائمة الحفظ.","question":"أي مشتق يدل على ما وقع عليه فعل الكتابة؟","correct":"مكتوب","wrong":["كاتب","كتابة","كتاب"],"practice":"أنشئ جدولًا لخمسة أنواع من المشتقات بصيغة ومثال ودلالة.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":3,"title":"اسم الفاعل","passage":"يصاغ اسم الفاعل من الثلاثي على وزن «فاعل» في القياس المعتاد: «كتب» منه «كاتب»، ومن غير الثلاثي وفق قواعد صياغته من المضارع. وقد يعمل عمل فعله بشروط نحوية، فلا نخلط بين الصيغة الصرفية ووظيفة الفاعل الإعرابية.","question":"ما اسم الفاعل من الفعل «كتب»؟","correct":"كاتب","wrong":["مكتوب","كتابة","مكتب"],"practice":"اشتق خمسة أسماء فاعل من أفعال ثلاثية وغير ثلاثية وضعها في جمل مفيدة.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":4,"title":"صيغ المبالغة","passage":"صيغ المبالغة مشتقات تدل في استعمالها على كثرة وقوع الفعل أو شدة الاتصاف به، ومن أوزانها «فعّال» و«فعول» و«مفعال»، وتفهم الدلالة بمراعاة السياق. في «صبور» صيغة مبالغة على وزن فعول.","question":"ما وزن صيغة المبالغة «صبور»؟","correct":"فعول","wrong":["فاعل","مفعول","مَفْعَل"],"practice":"اختر ثلاث صيغ مبالغة مع أفعالها وأوزانها، واذكر أثر السياق.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":5,"title":"صيغة اسم المفعول","passage":"يشتق اسم المفعول من الفعل الثلاثي المتعدي غالبًا على «مفعول»، مثل «مكتوب» من كتب، وقد تتغير الصورة مع الأفعال المعتلة. ومن غير الثلاثي تتبع صياغته قواعد مختلفة، ويحدد المعنى ما وقع عليه الفعل.","question":"أي كلمة اسم مفعول من «كتب»؟","correct":"مكتوب","wrong":["كاتب","كتاب","كتابة"],"practice":"حوّل أربعة أفعال متعدية إلى أسماء مفعول مع استعمال كل واحد في سياق.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":6,"title":"إعمال اسم الفاعل واسم المفعول","passage":"قد يعمل اسم الفاعل عمل فعله المتعدي مع شروط مثل الاعتماد على نفي أو استفهام أو موصوف، وقد يعمل اسم المفعول عمل الفعل المبني للمجهول فيرفع نائب فاعل. الحكم على العمل يعتمد التركيب والسياق لا مجرد الوزن.","question":"ما الأساس في تحديد عمل المشتق؟","correct":"معناه وشروط الاعتماد وتركيبه","wrong":["عدد الحروف وحده","أول حرف في الجملة","علامة الترقيم"],"practice":"حلل مثالين لاسم فاعل عامل وآخرين لاسم مفعول عامل بمصادر موثوقة.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"9328be63-aaec-4d94-b304-f5c00e832c8d","n":7,"title":"صيغ الصفة المشبهة باسم الفاعل","passage":"تدل الصفة المشبهة غالبًا على صفة ثابتة أو مستقرة في أصل معناها، وقد تصاغ من الفعل اللازم، مثل «حَسَن» و«كريم» في أمثلة لغوية مألوفة. تختلف صيغها وأحكام عملها عن اسم الفاعل، ولا يلزم أن تكون الصفة ثابتة دائمًا في الواقع.","question":"أي كلمة قد تستعمل صفة مشبهة؟","correct":"كريم","wrong":["كتب","لن","إنْ"],"practice":"اكتب أربع صفات مشبهة وصنف أوزانها ووضح دلالتها.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"14b62a41-b7e4-4178-aa9b-442835d254a3","n":1,"title":"الجمل وأشباه الجمل التي لها محل من الإعراب — مراجعة","passage":"تقع الجمل وشبه الجمل في مواضع تؤدي فيها وظائف إعرابية وفق التركيب؛ فقد تقع جملة فعلية خبرًا كما في «الطالب يقرأُ كتابه» حيث الجملة الفعلية في محل رفع خبر. لا تُعد كل جملة تابعة لاسم سابق نعتًا إلا بعد اختبار الموقع والتعريف والسياق.","question":"ما محل «يقرأ كتابه» في «الطالب يقرأ كتابه»؟","correct":"في محل رفع خبر","wrong":["في محل نصب مفعول به","بدل مفرد","لا محل لها دومًا"],"practice":"حلل خمس جمل وشبه جمل متنوعة من حيث نوعها ومحلها الإعرابي.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":1,"title":"صيغة النسب","passage":"تدل النسبة الصرفية على الانتساب إلى اسم بإضافة ياء مشددة مع كسرة قبلها غالبًا، مثل «وطنِيّ» من «وطن». قد تتغير نهاية الاسم بحسب بنيته، فلا يُعتمد الإلحاق الآلي لياء دون مراعاة القاعدة.","question":"ما اللاحقة الأساسية في اسم النسب؟","correct":"ياء مشددة","wrong":["ألف مقصورة","همزة قطع","تاء جمع"],"practice":"انسب ستة أسماء متنوعة إلى الصيغة الصحيحة مع توضيح قاعدة التغيير.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":2,"title":"النسب إلى المقصور","passage":"الاسم المقصور ينتهي بألف لازمة؛ مثل «فتى»، وتتأثر النسبة إليه بعدد الأحرف وأصل الألف أو موقعها. من الاستعمالات «فتَوِيّ» للنسبة إلى «فتى»؛ ينبغي مراجعة قواعد المقصور المختلفة وليس قياس جميع الأسماء على مثال واحد.","question":"ما نوع الاسم «فتى» من حيث آخره؟","correct":"اسم مقصور","wrong":["اسم منقوص","اسم ممدود","جمع سالم"],"practice":"وازن بين النسب إلى اسمين مقصورين واكتب القاعدة لكل منهما من مرجع صرفي.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":3,"title":"النسب إلى المنقوص","passage":"الاسم المنقوص آخره ياء لازمة مكسور ما قبلها، مثل «القاضي». قد تطرأ تغييرات على يائه في النسب بحسب عدد أحرف الاسم وأحكام النسب، فلا يكفي إضافة ياء أخرى إلى الرسم الظاهر دون مراجعة.","question":"أي اسم منقوص في الخيارات؟","correct":"القاضي","wrong":["صحراء","فتى","كتاب"],"practice":"حلل صيغ النسب إلى ثلاثة أسماء منقوصة مع بيان تغير الياء.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":4,"title":"النسب إلى الممدود","passage":"الاسم الممدود آخره همزة بعد ألف زائدة، مثل «صحراء». يختلف حكم الهمزة في النسب إلى الممدود بحسب كونها أصلية أو منقلبة أو زائدة للتأنيث؛ ولذلك يتطلب إرجاع الاسم لأصله الصرفي قبل الإلحاق.","question":"ما نهاية الاسم الممدود؟","correct":"همزة قبلها ألف زائدة","wrong":["ياء قبلها كسرة","ألف مقصورة","تاء مربوطة دائمًا"],"practice":"قارن صيغ النسب إلى أسماء ممدودة مختلفة نوع الهمزة بمساعدة مرجع صرفي.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":5,"title":"النسب إلى ما فيه ياء مشددة","passage":"قد تؤثر الياء المشددة في بناء الاسم عند النسب، وتختلف الصورة بحسب موقعها ووزن الكلمة؛ لذلك لا تُكرر الياءات بلا ضبط. يلزم تقسيم الكلمة إلى أصل وزيادة ومعرفة حركاتها قبل تحديد الصيغة النهائية.","question":"ما الذي يجب تحليله قبل النسب إلى اسم ذي ياء مشددة؟","correct":"موقع الياء ووزن الاسم وأصله","wrong":["عدد الكلمات في الجملة","نوع الخط","علامة الوقف"],"practice":"اختر من كتاب الصرف ثلاثة أسماء فيها ياء مشددة، ودوّن النسب الموثق إليها.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":6,"title":"النسب إلى الاسم الثلاثي مكسور العين","passage":"يحتاج الاسم الثلاثي مكسور العين إلى فحص بنائه وحركاته عند النسب، وقد تُتبع فيه قاعدة لتغيير الكسرة أو تسكين بعض الحروف بحسب الباب. مثال «مَلِك» يُدرس بضبط الحركات أولًا لتجنب الخلط بينه وبين أوزان قريبة.","question":"ما المقصود بعين الكلمة الثلاثية؟","correct":"حرفها الأصلي الثاني","wrong":["حرفها الأخير","حرفها الأول","الهمزة فقط"],"practice":"زن ثلاثة أسماء ثلاثية مكسورة العين واشتق نسبتها من مرجع صرفي.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":7,"title":"النسب إلى الاسم الثلاثي محذوف اللام","passage":"قد يُحذف الحرف الأصلي الثالث من بعض الأسماء الثلاثية في صورتها المستعملة، وتحتاج النسبة إلى معرفة اللام المحذوفة وهل تعود في الاشتقاق. لا ينفع تخمين الجذر من الرسم الحالي وحده، فالمعجم يحدد الأصل.","question":"ما الذي تعنيه «لام الكلمة» صرفيًا؟","correct":"الحرف الأصلي الثالث","wrong":["لام التعريف","حرف الجر لام","الحرف الأول"],"practice":"اختر مثالًا معجميًا لثلاثي محذوف اللام واشرح ما يحدث عند النسب إليه.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":8,"title":"النسب إلى المركب","passage":"قد تنسب العربية إلى مركب إضافي أو مزجي أو إسنادي بطرق متعددة بحسب النوع والاستعمال المستقر؛ قد يقع حذف أو اختصار عند النسب، فلا يشتق نموذج واحد بصورة آلية لكل المركبات.","question":"ما الخطوة الأولى للنسب إلى مركب؟","correct":"تحديد نوع المركب الصرفي","wrong":["حذف المضاف دائمًا","إضافة الألف فقط","اعتبار كل مركب مفردًا"],"practice":"صنف ثلاثة مركبات إلى إضافة ومزج وإسناد، وراجع صيغة النسب إليها.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"},{"cid":"24e3881b-9860-41f6-af7e-214bb8df2227","unit":"0f175f5d-bcfa-40c9-937b-504e8137719f","n":9,"title":"النسب إلى المثنى والجمع","passage":"تحتاج النسبة إلى المثنى والجمع إلى تمييز لفظ التثنية والجمع من أصل المفرد، وقد يرجع الصرفي إلى المفرد عند النسب في حالات متعددة. في «المعلمان» يُميز الطالب الأصل «معلم» قبل الاشتقاق، مع مراجعة الاستثناءات.","question":"ما الأصل الذي يُرد إليه «المعلمان» عند التحليل؟","correct":"معلم","wrong":["علم","عليم","معلّمون"],"practice":"اشتق النسب إلى ثلاثة مثنيات وثلاثة جموع بعد مراجعة المفرد وأحكام الباب.","old":"DADYOOM_SD_G12_OFFICIAL_GRAMMAR"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='SD' AND c.id=r.cid
    AND g.grade_number=12 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'SD_G12_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'SD_G12_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'SD_G12_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'SD_G12_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_SD_G12_GRAMMAR_ORIGINAL_21_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_SD_G12_GRAMMAR_ORIGINAL_21_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_SD_G12_GRAMMAR_ORIGINAL_21_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SD_G12_GRAMMAR_ORIGINAL_21_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'SD_G12_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;